41	const PROCESSING_FEE = 5;
42	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
43	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
44	
45	/** The MHPCO price list; only the types pinned down by tests so far. */
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
56	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
57	
58	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
59	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
60	
61	const basePremiumFor = (item: Item): number => BASE_PREMIUMS[item.type];
62	
63	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
64	
65	const quote = (step: QuoteStep): StepResult => {
66	  const policyBasePremium = sum(step.items.map(basePremiumFor));
67	  const afterInitialAssessment = policyBasePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
68	  return { premium: roundUpToWholeG(afterInitialAssessment + PROCESSING_FEE) };
69	};
70	
71	const runStep = (step: Step): StepResult => {
72	  if (step.op === "quote") return quote(step);
73	  throw new Error(`Unsupported step: ${step.op}`);
74	};
75	
76	export const runScenario = (scenario: Scenario): ScenarioResult => ({
77	  results: scenario.steps.map(runStep),
78	});
